@@ -0,0 +1,34 @@
+import assert from 'node:assert/strict';
+import {readFileSync} from 'node:fs';
+const read = p => JSON.parse(readFileSync(p,'utf8'));
+const ledger=read('docs/p9.0.7.2.1-cross-register-ledger.json');
+const prev=read('docs/p9.0.7.2-exhaustiveness-gate.json');
+const ids=read('docs/p9.0.7-contemporary-evidence-ledger.json');
+const policy=read('docs/p9.0.4.3-promotion-policy.json');
+assert.equal(ledger.case_count,85);
+assert.equal(ledger.rows.length,85);
+assert.equal(new Set(ledger.rows.map(r=>r.actual_id)).size,85);
+assert.deepEqual(ledger.rows.map(r=>r.actual_id).sort(),ids.rows.map(r=>r.actual_id).sort());
+assert.deepEqual(ledger.rows.map(r=>r.actual_id).sort(),prev.identity_impact.map(r=>r.actual_id).sort());
+assert.equal(ledger.acts.length,6);
+assert.equal(ledger.procedural_administrative_identity_sources.length,3);
+assert.equal(ledger.year2025_procedural_amendments_identified,1);
+assert.equal(ledger.rows.filter(r=>r.official_guidance_effect==='REQUIRE_DISTRICT_AND_ROLE_DISAMBIGUATION').length,11);
+assert.equal(ledger.rows.filter(r=>r.official_guidance_effect==='REQUIRE_ANNEX_2_COMPATIBILITY_BINDING').length,4);
+assert.deepEqual(ledger.direct_target_155_acts.sort(),['PMR-2023-48-ZI-VII','PMR-2026-114-ZID-VIII']);
+assert.equal(ledger.acts.find(r=>r.id==='PMR-2023-48-ZI-VII').publication_id,'2023000445');
+assert.equal(ledger.acts.find(r=>r.id==='PMR-2023-49-ZI-VII').publication_id,'2023000446');
+const law114=ledger.acts.find(r=>r.id==='PMR-2026-114-ZID-VIII');
+assert.equal(law114.sha256,'c9d05f579677f176007bd6987bf11031c986299e180d9e98577715f7cb1cc566');
+assert.equal(law114.effective_asof_2026_10_15,false);
+assert.equal(ledger.year2025_absence_proven,false);
+assert.equal(ledger.individual_status_changes_certified,0);
+assert.equal(ledger.contemporary_full_polygon_control_certified,0);
+assert.equal(ledger.exhaustive_all_official_acts,false);
+assert(ledger.registry_comparison.every(r=>r.exhaustive_2023_2026===false));
+assert(ledger.rows.every(r=>r.legal_md_parent_preserved && r.verified_individual_status_change_from_laws_2023_2026===null && r.normative_current_status==='UNRESOLVED_MISSING_EXHAUSTIVE_PUBLICATION_AND_TEXT_VERSION_CHAIN' && r.effective_control==='NOT_CERTIFIED_FULL_POLYGON' && r.semantic_acceptance==='BLOCKED_INCOMPLETE' && r.p91_import_allowed===false));
+assert.equal(ledger.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(ledger.p91_import_allowed,false);
+assert.equal(policy.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(policy.p91_import_allowed,false);
+console.log('P90721_CROSS_REGISTER_FAIL_CLOSED_PASS: 6 act records, 85 unique identities, no exhaustive claim, no illegal promotion');
